key=np.array([[0,3,1],[4,3,0],[2,0,4]])
out=np.array([[2,4,0],[0,3,3],[4,0,1]])
for i in range(4):
 a=np.rot90(key,i)
 for f in range(2):
  b=np.fliplr(a) if f else a
  if np.array_equal(b!=0,out!=0):
   pairs={}
   ok=True
   for x,y in zip(b.flat,out.flat):
    if x:
     if x in pairs and pairs[x]!=y:ok=False
     pairs[x]=y
   print(i,f,pairs,ok,b.tolist())
